{
  "implementation": "def solve(case):
    passing = case['passing']
    failing = case['failing']
    required_diff = case['required_difference']

    pass_set = set(passing)
    diff = [x for x in failing if x not in pass_set]

    required_set = set(required_diff)
    if not required_set.issubset(set(diff)):
        raise ValueError('required_difference is not a subset of the difference')

    test_count = 0

    def test(subset_indices):
        nonlocal test_count
        test_count += 1
        subset_set = set(diff[i] for i in subset_indices)
        return 'FAIL' if required_set.issubset(subset_set) else 'PASS'

    def ddmin(s_indices):
        # s_indices is a list of integer indices (sorted ascending)
        if len(s_indices) == 1:
            return s_indices if test(s_indices) == 'FAIL' else []
        m = len(s_indices)
        granularity = 2
        while granularity <= m:
            part_len = m // granularity
            remainder = m % granularity
            subsets = []
            start = 0
            for i in range(granularity):
                extra = 1 if i < remainder else 0
                end = start + part_len + extra
                subsets.append(s_indices[start:end])
                start = end
            for subset in subsets:
                if test(subset) == 'FAIL':
                    return ddmin(subset)
                complement = [x for x in s_indices if x not in subset]
                if test(complement) == 'FAIL':
                    return ddmin(complement)
            granularity *= 2
        # try removing one element at a time
        for i in range(m):
            reduced = s_indices[:i] + s_indices[i+1:]
            if test(reduced) == 'FAIL':
                return ddmin(reduced)
        return s_indices

    full_indices = list(range(len(diff)))
    if not full_indices:
        # no difference, but required diff must be empty; check validity
        if required_set:
            raise ValueError('difference is empty but required_difference non-empty')
        isolated = []
        test_count = 1  # one test of the empty set
    else:
        # ensure full set fails
        if test(full_indices) != 'FAIL':
            raise ValueError('the full difference does not cause failure')
        minimal_indices = ddmin(full_indices)
        isolated = [diff[i] for i in minimal_indices]

    return {
        'isolated_difference': isolated,
        'tests': test_count
    }"
}
